cd <scratch> && cat > h2t.py <<'EOF'
import sys, re, html
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(s):
        super().__init__(); s.out=[]; s.skip=0
    def handle_starttag(s,t,a):
        if t in ('script','style','noscript'): s.skip+=1
        if t in ('p','div','li','h1','h2','h3','h4','h5','br','tr','blockquote'): s.out.append('\n')
        if t=='li': s.out.append('- ')
        if t in ('h2','h3','h4'): s.out.append('#'*int(t[1])+' ')
    def handle_endtag(s,t):
        if t in ('script','style','noscript'): s.skip-=1
        if t in ('p','div','li','h1','h2','h3','h4','h5','blockquote'): s.out.append('\n')
    def handle_data(s,d):
        if not s.skip: s.out.append(d)
p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
t=''.join(p.out)
t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'\n\s*\n+','\n',t)
print(t)
EOF
for s in 9-18 9-19 12-15 12-16 12-17 12-18 25-18 25-19 25-20; do python3 h2t.py r_${s}.html > t_${s}.txt; echo "$s $(wc -l < t_${s}.txt)"; done
